current.custom_css:
.m-custom-slideshow .m-slide__content .m-slide__description {
  text-transform: uppercase;
  letter-spacing: 0.1em;
  font-size: 14px;
  color: rgb(var(--color-body-text));
}

.sf__custom-html-block1 .m-scroll {
  height: 56px;
}

.m-newsletter-form__wrapper .m-newsletter-form--bordered .m-newsletter-form__input,
.m-newsletter-form__wrapper .m-newsletter-form--bordered .m-newsletter-form__button--icon {
  border-color: #000;
  border-radius: 0;
}

.m-header__desktop .m-header__search {
  border: none;
}

.m-footer--block .m-footer--block-title {
  font-size: 20px;
}

.sf__scrolling-text .sf__scrolling-text-inner a em {
  font-size: 14px;
  letter-spacing: 2px;
  font-weight: 500;
}

.m-custon-hero .m-hero__content .m-hero__subtitle {
  text-transform: capitalize;
  font-size: 20px;
}

.m-custon-hero .m-hero__content .m-hero__title {
  margin-bottom: 12px;
}

.m-custon-hero .m-hero__content .m-hero__text,
.m-custom-content-section .rte p {
  font-size: 14px;
  line-height: 21px;
  text-transform: uppercase;
  letter-spacing: 0.1em;
  color: rgb(var(--color-body-text));
}

.m-footer--block-newsletter .m-footer--block-newsletter-desc {
  margin-bottom: 16px;
  color: rgb(var(--color-body-text));
  text-transform: uppercase;
  letter-spacing: 0.1em;
  font-size: 14px;
}

@media (min-width: 1280px) {
  .m-custom-content-section h3 {
    font-size: 40px;
    line-height: 1.3;
    margin-bottom: 20px;
  }
}

@media (min-width: 1536px) {
  .m-custom-content-section-1 .m-image-card__inner .m-image-card__content .m-image-card__heading {
    font-size: 40px;
    margin-bottom: 30px;
  }
}

@media (min-width: 768px) {
  .m-footer .m-footer--block-newsletter .m-footer--block-title {
    font-size: 40px;
  }
}

@media (max-width: 767px) {
  .m-custom-content-section-1 .m-image-card__content {
    padding-left: 0;
    padding-right: 0;
  }

  .m-custom-content-section-1 .m-image-card__content .m-image-card__content-inner {
    width: 100%;
    text-align: left;
  }

  .m-richtext__description br,
  .m-press__title br,
  .m-custom-content-section h3 br,
  .m-custom-content-section-1 .m-image-card__content .m-image-card__heading br {
    display: none;
  }
}

.m-newsletter-form__wrapper {
  background-color: #fff;
}
